arguments.command:
python -c 'import re; import pandas as pd; from collections import defaultdict; df=pd.read_csv("b3_supercon_data.csv"); bounds=dict(O=.697674,Cu=.454545,Ba=.333333,Sr=.285714,Y=.4,Ca=.272727,La=.78,Bi=.521978,Fe=.502513,Nb=.98,C=.972,Pr=.265043,As=.5,B=1.,Pb=.5,Ce=.28,Mo=1.,V=.9918,Zn=1.,Ni=.6); rows=[]
for _,row in df.iterrows():
    formula=row["composition"]; tokens=re.findall(r"([A-Z][a-z]?)([0-9]*\.?[0-9]*)",formula); assert "".join(e+n for e,n in tokens)==formula; counts=defaultdict(float)
    for e,n in tokens: counts[e]+=float(n) if n else 1.
    total=sum(counts.values()); fractions={e:n/total for e,n in counts.items()}; excluded=sorted(set(fractions)-set(bounds)); violations=[e for e,x in fractions.items() if e in bounds and x>bounds[e]+1e-9]; rows.append({"composition":formula,"Tc":float(row["target"]),"fractions":fractions,"excluded":excluded,"violations":violations})
feasible=sorted([r for r in rows if not r["excluded"] and not r["violations"]],key=lambda r:r["Tc"],reverse=True); print("Samples:",len(rows)); print("Feasible using only design elements and stated bounds:",len(feasible)); print("Highest feasible samples:")
for r in feasible[:10]: print(r)
best=feasible[0]; print("Best fraction sum:",sum(best["fractions"].values())); print("All higher-Tc samples:")
for r in sorted(rows,key=lambda r:r["Tc"],reverse=True):
    if r["Tc"]>best["Tc"]: print(r)
print("PROPOSAL:",", ".join(str(e)+"="+format(best["fractions"].get(e,0),".6f") for e in bounds))'

